@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @bind="_query"
           @bind:event="oninput"
           @bind:after="OnQueryChangedAsync" />

    @if (_isLoading)
    {
        <div class="product-search__status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search__error">
            <span>Search failed: @_error</span>
            <button @onclick="RetryAsync">Retry</button>
        </div>
    }
    else if (_hasSearched && _results.Count == 0)
    {
        <div class="product-search__status">No products found.</div>
    }
    else if (_results.Count > 0)
    {
        <div class="product-search__results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" loading="lazy" />
                    <h3>@product.Name</h3>
                    <p>@product.Price.ToString("C")</p>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private List<Product> _results = new();
    private bool _isLoading;
    private bool _hasSearched;
    private string? _error;

    private CancellationTokenSource? _debounceCts;
    private CancellationTokenSource? _searchCts;

    private async Task OnQueryChangedAsync()
    {
        // Cancel any pending debounce timer.
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        _debounceCts = new CancellationTokenSource();
        var token = _debounceCts.Token;

        if (string.IsNullOrWhiteSpace(_query))
        {
            CancelInflightSearch();
            _results = new();
            _hasSearched = false;
            _error = null;
            _isLoading = false;
            return;
        }

        try
        {
            await Task.Delay(300, token);
        }
        catch (TaskCanceledException)
        {
            // User typed again before the debounce elapsed — nothing to do.
            return;
        }

        await ExecuteSearchAsync(_query);
    }

    private async Task ExecuteSearchAsync(string query)
    {
        // Cancel any previous in-flight search.
        CancelInflightSearch();
        _searchCts = new CancellationTokenSource();
        var token = _searchCts.Token;

        _isLoading = true;
        _error = null;

        try
        {
            _results = await ProductService.SearchAsync(query, token);
            _hasSearched = true;
        }
        catch (OperationCanceledException)
        {
            // Search was superseded by a newer query — discard silently.
            return;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _results = new();
        }
        finally
        {
            // Only clear loading if this search wasn't cancelled.
            if (!token.IsCancellationRequested)
            {
                _isLoading = false;
            }
        }
    }

    private async Task RetryAsync() => await ExecuteSearchAsync(_query);

    private void CancelInflightSearch()
    {
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = null;
    }

    public void Dispose()
    {
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        CancelInflightSearch();
    }
}

